/* Philadelphia 76ers DNA — liberty navy night, stars and red */
.theme-philadelphia-76ers {
  --bg: oklch(0.236 0.066 260.9);
  --surface: oklch(0.272 0.069 259.6);
  --surface-2: oklch(0.314 0.074 258.1);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.732 0.043 262.2);
  --accent: oklch(0.606 0.234 17.1);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(1.000 0 0);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.615 0.190 27.8);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Big Shoulders", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-philadelphia-76ers h1,
.theme-philadelphia-76ers h2,
.theme-philadelphia-76ers h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-philadelphia-76ers { --font-ui: var(--font-display); }
.theme-philadelphia-76ers h1, .theme-philadelphia-76ers h2 { text-transform: uppercase; font-weight: 800; }
.theme-philadelphia-76ers button { text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }

.theme-philadelphia-76ers h1::before { content: "★ ★ ★"; display: block; font-size: 0.32em; letter-spacing: 0.7em; color: #ffffff; margin-bottom: 0.5rem; }
.theme-philadelphia-76ers h1 { color: #ffffff; }

/* depth */
.theme-philadelphia-76ers ::selection { background: var(--accent); color: #ffffff; }
.theme-philadelphia-76ers a { color: oklch(0.74 0.15 17); text-decoration-color: color-mix(in oklab, var(--accent) 55%, transparent); text-underline-offset: 3px; }
.theme-philadelphia-76ers a:hover { color: #ffffff; text-decoration-color: var(--accent); text-decoration-thickness: 2px; }
.theme-philadelphia-76ers thead th { font-family: var(--font-display); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.8em; color: var(--fg-muted); background: oklch(0.205 0.062 261); border-bottom: 2px solid var(--accent); }
.theme-philadelphia-76ers td { border-bottom: 1px solid var(--line); }
.theme-philadelphia-76ers tbody tr:hover { background: oklch(0.606 0.234 17.1 / 9%); }
.theme-philadelphia-76ers input, .theme-philadelphia-76ers select, .theme-philadelphia-76ers textarea { background: oklch(0.20 0.060 261); border: 1px solid var(--line); caret-color: var(--accent); }
.theme-philadelphia-76ers input:focus-visible, .theme-philadelphia-76ers select:focus-visible, .theme-philadelphia-76ers textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px oklch(0.606 0.234 17.1 / 28%); }
/* jersey number plate */
.theme-philadelphia-76ers kbd { font-family: var(--font-display); font-weight: 800; background: #ffffff; color: oklch(0.236 0.066 260.9); border: 2px solid var(--accent); border-radius: var(--radius-sm); padding: 0.1em 0.5em; }
.theme-philadelphia-76ers ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-philadelphia-76ers ::-webkit-scrollbar-track { background: oklch(0.20 0.060 261); }
.theme-philadelphia-76ers ::-webkit-scrollbar-thumb { background: oklch(0.48 0.17 17); border: 2px solid oklch(0.20 0.060 261); border-radius: 999px; }
.theme-philadelphia-76ers ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-philadelphia-76ers .label-caps { color: oklch(0.74 0.15 17); font-weight: 700; }
.theme-philadelphia-76ers .label-caps::before { content: "★ "; color: #ffffff; }
/* physical: liberty trim — double-ruled borders like the flag field */
.theme-philadelphia-76ers .themed-border { border-style: double; border-width: 3px; border-color: oklch(1 0 0 / 40%); }
.theme-philadelphia-76ers button:hover { box-shadow: inset 0 -3px 0 var(--accent), var(--shadow-1); }
.theme-philadelphia-76ers button:active { transform: translateY(1px); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-philadelphia-76ers.alt-mode {
  --bg: oklch(0.985 0 0);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.953 0.003 286.3);
  --fg: oklch(0.206 0.006 285.9);
  --fg-muted: oklch(0.478 0.016 285.8);
  --accent: oklch(0.606 0.234 17.1);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.518 0.143 249.1);
  --line: oklch(0.914 0.005 286.3);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}
.theme-philadelphia-76ers.alt-mode h1 { background: none; -webkit-background-clip: initial; background-clip: initial; color: #ed174c; -webkit-text-stroke: 0; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
